const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Keukenhof Garden geometry
  const keukenhof = ee.Geometry.Point([4.46, 52.27]).buffer(500); // 500m buffer around center

  // Define time periods
  const date1_start = '2018-04-15';
  const date1_end = '2018-04-25';
  const date2_start = '2018-05-01';
  const date2_end = '2018-05-15';

  // Function to mask clouds using SCL
  const maskClouds = (image) => {
    const scl = image.select('SCL');
    const cloudMask = scl.lt(4).or(scl.gt(8)); // Mask clouds, shadows, snow
    return image.updateMask(cloudMask);
  };

  // Function to detect red flowers: high red reflectance
  const detectRedFlowers = (image) => {
    const red = image.select('B4');
    const green = image.select('B3');
    const blue = image.select('B2');
    const redFlower = red.gt(0.2).and(red.gt(green)).and(red.gt(blue));
    return image.addBands(redFlower.rename('red_flowers'));
  };

  // Collect Sentinel-2 images for April 21, 2018
  let col1 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(keukenhof)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size1 = col1.size().getInfo();
  console.log(`April 2018 Images: ${size1}`);

  if (size1 === 0) {
    console.log('C1');
    return;
  }

  // Collect Sentinel-2 images for May 7, 2018
  let col2 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(keukenhof)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size2 = col2.size().getInfo();
  console.log(`May 2018 Images: ${size2}`);

  if (size2 === 0) {
    console.log('C1');
    return;
  }

  // Process April images
  col1 = col1.map(maskClouds).map(detectRedFlowers);
  const img1 = col1.median();

  // Process May images
  col2 = col2.map(maskClouds).map(detectRedFlowers);
  const img2 = col2.median();

  // Calculate red flower statistics for April
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: keukenhof,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const redMean1 = stats1['B4_mean'] || 0;
  const count1 = stats1['B4_count'] || 0;

  // Calculate red flower statistics for May
  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: keukenhof,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const redMean2 = stats2['B4_mean'] || 0;
  const count2 = stats2['B4_count'] || 0;

  console.log(`April 21 Red Mean: ${redMean1?.toFixed(3)} Pixels: ${count1}`);
  console.log(`May 7 Red Mean: ${redMean2?.toFixed(3)} Pixels: ${count2}`);

  // Validate results
  if (count1 === 0 || count2 === 0) {
    console.log('C2');
    return;
  }

  if (redMean1 === null || redMean2 === null || isNaN(redMean1) || isNaN(redMean2)) {
    console.log('C3');
    return;
  }

  // Compare red flower intensity
  if (redMean1 > redMean2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
